/* Local-only helpers for the static guide, manual directory and report composer. */
const printPlan=document.getElementById('print-plan');if(printPlan)printPlan.onclick=()=>window.print();
const manualSearch=document.getElementById('manual-search');if(manualSearch){const cards=[...document.querySelectorAll('.manual-card')],count=document.getElementById('manual-count');const filter=()=>{const value=manualSearch.value.trim().toLocaleLowerCase();let n=0;for(const card of cards){card.hidden=!card.dataset.search.includes(value);if(!card.hidden)n++;}count.textContent=n+' of '+cards.length+' document entries'+(n?'':' · No match. Try a brand or model.');};manualSearch.addEventListener('input',filter);filter();}
const reportForm=document.getElementById('report-form');if(reportForm){let draft='';reportForm.addEventListener('submit',event=>{event.preventDefault();if(!reportForm.reportValidity())return;const data=new FormData(reportForm),type=data.get('type'),model=String(data.get('model')).trim();draft=['## '+type,'','Controller: '+(model||'Not specified'),'Arena / region: '+(data.get('arena')||'Not specified'),'Public source: '+(data.get('source')||'Not supplied'),'','## Details',String(data.get('details')).trim()].join('\n');document.getElementById('report-body').textContent=draft;const url=new URL('https://github.com/davejcameron/rink-timekeeper/issues/new');url.searchParams.set('title',type+': '+(model||'Rinkside Clock'));url.searchParams.set('body',draft);document.getElementById('report-github').href=url.href;document.getElementById('report-preview').hidden=false;document.getElementById('report-status').textContent='Draft prepared. Review and submit it on GitHub; nothing has been sent.';});document.getElementById('copy-report').onclick=async()=>{try{await navigator.clipboard.writeText(draft);document.getElementById('report-status').textContent='Copied. You can paste this into a GitHub issue.';}catch{document.getElementById('report-status').textContent='Select the draft text and copy it using your device’s copy command.';}};}
